import{_ as t,o as a,c as r,l as s,t as o,N as n}from"./chunks/framework.Bbd9fWQx.js";const b=JSON.parse('{"title":"shred | x-cmd man (man1) | overwrite a file to hide its contents, and optionally delete it","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | shred - overwrite a file to hide its contents, and optionally delete it","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"shred | x-cmd man (man1) | overwrite a file to hide its contents, and optionally delete it"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | shred - overwrite a file to hide its contents, and optionally delete it"}]]},"headers":[],"params":{"isMan":true,"man":"shred","category":"man1","desc":"overwrite a file to hide its contents, and optionally delete it"},"relativePath":"man1/shred.md","filePath":"man1/shred.md"}'),i={name:"man1/shred.md"},d={class:"visually-hidden"},l=n('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>shred - overwrite a file to hide its contents, and optionally delete it</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>shred</strong> [<em>OPTION</em>]... <em>FILE</em>...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Overwrite the specified FILE(s) repeatedly, in order to make it harder for even very expensive hardware probing to recover the data.</p><p>If FILE is -, shred standard output.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>-f</strong>, <strong>--force</strong></dt><dd>change permissions to allow writing if necessary</dd><dt><strong>-n</strong>, <strong>--iterations</strong>=<em>N</em></dt><dd>overwrite N times instead of the default (3)</dd><dt><strong>--random-source</strong>=<em>FILE</em></dt><dd>get random bytes from FILE</dd><dt><strong>-s</strong>, <strong>--size</strong>=<em>N</em></dt><dd>shred this many bytes (suffixes like K, M, G accepted)</dd><dt><strong>-u</strong></dt><dd>deallocate and remove file after overwriting</dd><dt><strong>--remove</strong>[=<em>HOW</em>]</dt><dd>like <strong>-u</strong> but give control on HOW to delete; See below</dd><dt><strong>-v</strong>, <strong>--verbose</strong></dt><dd>show progress</dd><dt><strong>-x</strong>, <strong>--exact</strong></dt><dd>do not round file sizes up to the next full block;</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">this</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> is</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> for</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> non-regular</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> files</span></span></code></pre></div><dl><dt><strong>-z</strong>, <strong>--zero</strong></dt><dd>add a final overwrite with zeros to hide shredding</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>Delete FILE(s) if <strong>--remove</strong> (<strong>-u</strong>) is specified. The default is not to remove the files because it is common to operate on device files like <em>/dev/hda</em>, and those files usually should not be removed. The optional HOW parameter indicates how to remove a directory entry: &#39;unlink&#39; =&gt; use a standard unlink call. &#39;wipe&#39; =&gt; also first obfuscate bytes in the name. &#39;wipesync&#39; =&gt; also sync each obfuscated byte to the device. The default mode is &#39;wipesync&#39;, but note it can be expensive.</p><p>CAUTION: shred assumes the file system and hardware overwrite data in place. Although this is common, many platforms operate otherwise. Also, backups and mirrors may contain unremovable copies that will let a shredded file be recovered later. See the GNU coreutils manual for details.</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Colin Plumb.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/shred%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/shred\\</a>&gt; <br> or available locally via: info &#39;(coreutils) shred invocation&#39;</p>',21);function h(e,p,c,g,m,u){return a(),r("div",null,[s("h1",d,o(e.$params.man),1),l])}const y=t(i,[["render",h]]);export{b as __pageData,y as default};
